 mistakes=[("I am teacher.", "I am a teacher.", "Tekil sayılabilen isim yalnız kalmaz."), ("The life is beautiful.", "Life is beautiful.", "Genel anlamda soyut isme the gelmez."), ("a apple", "an apple", "Sesli sesten önce an.")],
 quiz=[dict(q="She is ___ honest person.", o=["a", "an", "the"], a=1, why="honest /ɒ/ sesiyle başlar (h okunmaz)"), dict(q="Look at ___ moon!", o=["a", "an", "the"], a=2, why="Tek olan şey: the moon"), dict(q="I need ___ umbrella.", o=["a", "an", "the"], a=1, why="umbrella sesli sesle başlar")],
